// Trade Cars — Funnel desde Chatwoot. Traduce el evento de Chatwoot a:
//   1) el payload que espera POST /api/tradecars/funnel-lead, y
//   2) la etiqueta (cumple_politica / no_coincide) que debe llevar la conversacion.
//
// REESCRITO el 18/09/2026 tras la reunion de alineacion con Trade Cars.
// El embudo se arma en cascada con DOS custom attributes de Chatwoot:
//
//   coincide  (lista)  ✓ / x
//   estado    (lista)  No contactado · No interesado · En seguimiento · Cita · Cita asistida · Concretado
//
//   LEADS            todo lo que entra
//   CUMPLE POLITICA  coincide ✓  (con cualquiera de los 6 estados, o todavia sin estado)
//   CONTACTADO       coincide ✓ + {No interesado, En seguimiento, Cita, Cita asistida, Concretado}
//   INTERESADOS      coincide ✓ + {En seguimiento, Cita, Cita asistida, Concretado}
//   CITAS AGENDADAS  coincide ✓ + {Cita, Cita asistida, Concretado}
//   CITAS ASISTIDAS  coincide ✓ + {Cita asistida, Concretado}
//   COMPRAS          coincide ✓ + Concretado
//
// El calculo de las barras NO se hace aqui: el dashboard lo hace con estos dos datos
// (utils/tradecarsFunnel.ts + columnas GENERATED en la BD). Este nodo solo traduce el
// valor de Chatwoot al formato que entiende el endpoint y decide la etiqueta.
//
// Reglas que aplica este nodo:
//  - coincide x (NO)  -> el estado se BLOQUEA: se manda vacio aunque Chatwoot traiga uno.
//  - coincide ✓ (SI)  -> etiqueta cumple_politica.   coincide x -> etiqueta no_coincide.
//  - "Concretado" (Chatwoot, masculino) -> "CONCRETADA" (valor del dashboard).
//  - Dos opciones del dropdown `estado` traen un TAB escondido delante ("\tNo interesado",
//    "\tEn seguimiento"): se limpia con trim() antes de comparar.
//  - Solo se mandan los datos que existen. Un atributo vacio NO se envia como null: asi un
//    evento de Chatwoot nunca borra fechas ni ediciones hechas desde el dashboard.
//
// BUG REAL corregido el 14/09/2026 (se mantiene): el nodo Webhook de n8n SIEMPRE envuelve el
// POST real dentro de item.json.body (item.json = { headers, params, query, body, ... }).
// Leer directo de item.json daba todo vacio sin ningun error visible. Al probar con un payload
// pegado a mano hay que simular ese sobre, no pasar el cuerpo de Chatwoot pelado.

const ACCOUNT_TRADECARS = 17;
const ETIQUETAS_GESTIONADAS = ['cumple_politica', 'no_coincide'];

// Caracteres invisibles / acentos sin usar escapes \u (algunos editores los convierten).
const VS16 = String.fromCharCode(0xFE0F); // selector de emoji: convierte ✔ en ✔️
const RE_ACENTOS = new RegExp('[' + String.fromCharCode(0x0300) + '-' + String.fromCharCode(0x036F) + ']', 'g');

const limpiar = (v) => String(v === null || v === undefined ? '' : v).split(VS16).join('').trim().toLowerCase();
const claveEstado = (v) => limpiar(v).normalize('NFD').replace(RE_ACENTOS, '').replace(/[_\s-]+/g, ' ').trim();

// Coincide: ✓ / x. Vacio = todavia sin calificar (NO es lo mismo que x).
const COINCIDE_SI = ['✓', '✔', '✅', '☑', 'si', 'sí', 'yes', 'true', '1'];
const COINCIDE_NO = ['x', '✗', '✘', '✖', '❌', '×', 'no', 'false', '0'];
const perfilDe = (v) => {
  const s = limpiar(v);
  if (!s) return '';
  if (COINCIDE_SI.includes(s)) return 'SI';
  if (COINCIDE_NO.includes(s)) return 'NO';
  return '';
};

// estado (Chatwoot) -> STATUS (dashboard)
const ESTADO_A_STATUS = {
  'no contactado':  'NO CONTACTADO',
  'no interesado':  'NO INTERESADO',
  'en seguimiento': 'EN SEGUIMIENTO',
  'cita':           'CITA',
  'cita asistida':  'CITA ASISTIDA',
  'concretado':     'CONCRETADA',
  'concretada':     'CONCRETADA',
};

// Compatibilidad con las conversaciones que todavia traen el estado del esquema anterior
// (7 etapas en un solo campo, del 14/09). Ese formato no tenia "coincide": lo deduce el estado.
const ESTADO_LEGADO = {
  'lead':            { perfil: '',   status: '' },
  'cumple politica': { perfil: 'SI', status: 'NO CONTACTADO' },
  'contactado':      { perfil: 'SI', status: 'NO INTERESADO' },
  'interesado':      { perfil: 'SI', status: 'EN SEGUIMIENTO' },
  'cita agendada':   { perfil: 'SI', status: 'CITA' },
  'compra':          { perfil: 'SI', status: 'CONCRETADA' },
};

// Canal e inboxes de Trade Cars (confirmados por el cliente el 14/09/2026).
// Si se agrega un inbox nuevo, agregar su id en INBOX_A_CANAL e INBOX_A_CAMPANA.
const INBOX_A_CANAL = { 88: 'WhatsApp', 81: 'Instagram', 82: 'TikTok', 83: 'Facebook' };
const CANALES_POR_TIPO = {
  'Channel::Whatsapp': 'WhatsApp',
  'Channel::Instagram': 'Instagram',
  'Channel::FacebookPage': 'Facebook',
  'Channel::Tiktok': 'TikTok',
  'Channel::Api': 'API',
  'Channel::WebWidget': 'Web',
  'Channel::Email': 'Email',
};
// La campana ES el canal de origen (decision del cliente, 14/09). Ojo: el inbox 83 es
// "Facebook" como canal pero "Messenger" como campana. "WEB" queda reservado para cuando
// se conecte el formulario de la web.
const INBOX_A_CAMPANA = { 88: 'WhatsApp', 81: 'Instagram', 82: 'TikTok', 83: 'Messenger' };

// Fechas en hora de Lima (UTC-5 todo el año). Antes se cortaba el ISO en UTC y una
// conversacion creada despues de las 19:00 en Lima caia en el dia siguiente (y a fin de
// mes, en el mes siguiente del embudo).
const LIMA_MS = 5 * 3600 * 1000;
const aFecha = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const aDia = (ms) => new Date(ms - LIMA_MS).toISOString().slice(0, 10);
  if (typeof v === 'number') return aDia(v * 1000);
  const s = String(v).trim();
  if (/^\d{10}$/.test(s)) return aDia(Number(s) * 1000);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : aDia(d.getTime());
};

const salida = [];

for (const item of $input.all()) {
  const raw = item.json || {};

  // El POST real de Chatwoot esta en .body; el fallback cubre pruebas pegando solo el cuerpo.
  const c = raw.body !== undefined && raw.body !== null ? raw.body : raw;

  // Segun el evento, la conversacion viene plana o anidada en .conversation
  const conv  = c.conversation || c;
  const attrs = conv.custom_attributes || c.custom_attributes || {};
  const meta  = conv.meta || c.meta || {};

  const conversationId = conv.id !== undefined ? conv.id : null;
  const accountIdRaw = conv.account_id !== undefined ? conv.account_id
    : (c.account && c.account.id !== undefined ? c.account.id
    : (conv.messages && conv.messages[0] ? conv.messages[0].account_id : undefined));
  const accountId = accountIdRaw !== undefined && accountIdRaw !== null ? Number(accountIdRaw) : ACCOUNT_TRADECARS;

  // ── Coincide + estado ─────────────────────────────────────────────
  const perfilAttr = perfilDe(attrs.coincide !== undefined ? attrs.coincide : attrs.perfil_coincide);
  const estadoKey  = claveEstado(attrs.estado !== undefined ? attrs.estado : attrs.status);

  let perfil = perfilAttr;
  let status = '';
  let estadoReconocido = false;

  if (ESTADO_A_STATUS[estadoKey]) {
    status = ESTADO_A_STATUS[estadoKey];
    estadoReconocido = true;
  } else if (ESTADO_LEGADO[estadoKey]) {
    status = ESTADO_LEGADO[estadoKey].status;
    if (!perfil) perfil = ESTADO_LEGADO[estadoKey].perfil;
    estadoReconocido = true;
  } else if (estadoKey) {
    // Opcion nueva sin avisar, typo, etc.: NO se manda status para no borrar por error una
    // clasificacion que el lead ya tenia.
    console.log('[tradecars-funnel] estado no reconocido, se ignora: "' + estadoKey + '" (conv ' + conversationId + ')');
  }

  // Coincide = x  ->  el estado se bloquea (se manda vacio)
  const statusBloqueado = perfil === 'NO';
  if (statusBloqueado) status = '';

  const enviar = perfil !== '' || estadoReconocido;

  // ── Etiqueta de la conversacion ───────────────────────────────────
  // Solo las dos que maneja este flujo; las de estado (no_contactado, cita, ...) las siguen
  // poniendo las automatizaciones de Chatwoot y NO se tocan.
  const etiquetasEnEvento = (conv.labels || c.labels || []).map(String);
  const yaTieneGestionada = etiquetasEnEvento.some((l) => ETIQUETAS_GESTIONADAS.includes(l));
  const etiquetaDeseada = perfilAttr === 'SI' ? 'cumple_politica' : (perfilAttr === 'NO' ? 'no_coincide' : '');
  // Se sincroniza cuando el asesor marco coincide, o cuando quedo una etiqueta vieja sin coincide.
  const sincronizarEtiquetas = !!conversationId && accountId === ACCOUNT_TRADECARS
    && (perfilAttr !== '' || yaTieneGestionada);

  // ── Datos automaticos del CRM ─────────────────────────────────────
  const inboxId = conv.inbox_id !== undefined ? conv.inbox_id : (c.inbox_id !== undefined ? c.inbox_id : null);
  const canal   = INBOX_A_CANAL[inboxId] || CANALES_POR_TIPO[conv.channel] || conv.channel || '';
  const campana = INBOX_A_CAMPANA[inboxId] || '';

  const payload = {
    conversation_id:  conversationId,
    account_id:       accountId,
    contact_id:       meta.sender && meta.sender.id !== undefined ? meta.sender.id : null,
    nombre:           (meta.sender && meta.sender.name) || '',
    telefono:         (meta.sender && meta.sender.phone_number) || '',
    canal,
    campana,
    asesor:           (meta.assignee && meta.assignee.name) || '',
    fecha_derivacion: aFecha(conv.created_at),
  };

  // Solo se mandan los datos que Chatwoot realmente trae.
  if (perfil) payload.perfil_coincide = perfil;
  if (statusBloqueado || estadoReconocido) payload.status = status;

  const infoAuto = String(
    attrs.informacion_del_auto !== undefined ? attrs.informacion_del_auto
      : (attrs.informacion_auto !== undefined ? attrs.informacion_auto : (attrs.info_auto || ''))
  ).trim();
  if (infoAuto) payload.informacion_auto = infoAuto;

  // Atributos opcionales de seguimiento (hoy Chatwoot no los tiene; se dejan por si se crean).
  const fCita = aFecha(attrs.fecha_cita);
  const fCompra = aFecha(attrs.fecha_compra);
  const fProbable = aFecha(attrs.fecha_probable_venta);
  const fSeguimiento = aFecha(attrs.fecha_seguimiento);
  if (fCita) payload.fecha_cita = fCita;
  if (fCompra) payload.fecha_compra = fCompra;
  if (fProbable) payload.fecha_probable_venta = fProbable;
  if (fSeguimiento) payload.fecha_seguimiento = fSeguimiento;
  if (attrs.motivo_no_cita) payload.motivo_no_cita = String(attrs.motivo_no_cita);
  if (attrs.proxima_accion) payload.proxima_accion = String(attrs.proxima_accion);

  // Campos de control del flujo (el endpoint del dashboard los ignora).
  payload._enviar = enviar;
  payload._sync_etiquetas = sincronizarEtiquetas;
  payload._etiqueta_deseada = etiquetaDeseada;

  salida.push({ json: payload });
}

return salida;

// Decide que etiquetas debe llevar la conversacion, sin tocar las que no maneja este flujo.
//
// Chatwoot: POST /conversations/{id}/labels REEMPLAZA la lista completa, asi que se parte de
// la lista ACTUAL (leida recien en el nodo anterior, no la del webhook, que puede estar
// desactualizada por las automatizaciones de estado) y solo se cambian cumple_politica /
// no_coincide. Si no hay nada que cambiar, la rama termina aqui: es lo que evita el bucle
// (el propio POST dispara otro webhook, que llega, compara, ve que ya esta bien y no hace nada).

const GESTIONADAS = ['cumple_politica', 'no_coincide'];

const base = $('Armar payload').first().json;
const respuesta = $input.first().json || {};

// Si Chatwoot no devolvio la lista (error de red, token, etc.) no se toca nada.
if (!Array.isArray(respuesta.payload)) {
  return [{ json: { cambiar: false, motivo: 'no se pudo leer la lista actual de etiquetas' } }];
}

const actuales = respuesta.payload.map(String);
const deseada = base._etiqueta_deseada || '';

const resto = actuales.filter((l) => !GESTIONADAS.includes(l));
const nuevas = deseada ? [...resto, deseada] : resto;

const mismas = nuevas.length === actuales.length && nuevas.every((l) => actuales.includes(l));

return [{
  json: {
    cambiar: !mismas,
    account_id: base.account_id,
    conversation_id: base.conversation_id,
    etiquetas_antes: actuales,
    etiquetas_despues: nuevas,
  },
}];
